CREATE DATABASE IF NOT EXISTS carelink CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE carelink;
CREATE TABLE IF NOT EXISTS patients(patient_id BIGINT PRIMARY KEY AUTO_INCREMENT,health_id VARCHAR(40) NOT NULL UNIQUE,full_name VARCHAR(120) NOT NULL,date_of_birth DATE,gender VARCHAR(30),phone VARCHAR(25),email VARCHAR(120),address VARCHAR(255),blood_group VARCHAR(8),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS doctors(doctor_id BIGINT PRIMARY KEY AUTO_INCREMENT,full_name VARCHAR(120) NOT NULL,specialization VARCHAR(100),phone VARCHAR(25),email VARCHAR(120),department VARCHAR(100),consultation_fee DECIMAL(10,2) DEFAULT 0) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS appointments(appointment_id BIGINT PRIMARY KEY AUTO_INCREMENT,patient_id BIGINT NOT NULL,doctor_id BIGINT NOT NULL,appointment_date DATETIME NOT NULL,status VARCHAR(30) DEFAULT 'Scheduled',reason VARCHAR(255),FOREIGN KEY(patient_id) REFERENCES patients(patient_id),FOREIGN KEY(doctor_id) REFERENCES doctors(doctor_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS medical_records(record_id BIGINT PRIMARY KEY AUTO_INCREMENT,patient_id BIGINT NOT NULL,doctor_id BIGINT,record_date DATE NOT NULL,diagnosis VARCHAR(255) NOT NULL,notes TEXT,hospital_name VARCHAR(150) NOT NULL,record_category VARCHAR(80) DEFAULT 'General',FOREIGN KEY(patient_id) REFERENCES patients(patient_id),FOREIGN KEY(doctor_id) REFERENCES doctors(doctor_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS medicines(medicine_id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) NOT NULL,category VARCHAR(80),stock_quantity INT DEFAULT 0,unit_price DECIMAL(10,2) DEFAULT 0,expiry_date DATE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS admissions(admission_id BIGINT PRIMARY KEY AUTO_INCREMENT,patient_id BIGINT NOT NULL,bed_number VARCHAR(30) NOT NULL,admission_date DATETIME NOT NULL,discharge_date DATETIME,status VARCHAR(30) DEFAULT 'Admitted',FOREIGN KEY(patient_id) REFERENCES patients(patient_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS bills(bill_id BIGINT PRIMARY KEY AUTO_INCREMENT,patient_id BIGINT NOT NULL,bill_date DATE NOT NULL,total_amount DECIMAL(12,2) DEFAULT 0,paid_amount DECIMAL(12,2) DEFAULT 0,payment_status VARCHAR(30) DEFAULT 'Pending',description VARCHAR(255),FOREIGN KEY(patient_id) REFERENCES patients(patient_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS patient_consents(consent_id BIGINT PRIMARY KEY AUTO_INCREMENT,patient_id BIGINT NOT NULL,health_id VARCHAR(40) NOT NULL,requesting_hospital VARCHAR(150) NOT NULL,record_scope VARCHAR(255) NOT NULL,granted_at DATETIME NOT NULL,expires_at DATETIME NOT NULL,status VARCHAR(30) DEFAULT 'Pending',FOREIGN KEY(patient_id) REFERENCES patients(patient_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit_logs(audit_id BIGINT PRIMARY KEY AUTO_INCREMENT,actor VARCHAR(120),action VARCHAR(100) NOT NULL,entity_type VARCHAR(80),entity_id VARCHAR(80),details TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
